items[0].binary.data.fileName = `$('输入关键词和你的邮箱地址').first().json.key_word.pdf`

return items;

const items = $input.all();

const keyword = $('输入关键词和你的邮箱地址').first().json.key_word;

let readerHtml = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>${keyword}文章推送</title>
<style>
body {
  font-family: 'Georgia','宋体','Times New Roman',serif;
  background:#faf9f8;
  color:#2c3e50;
  line-height:1.8;
  margin:0;
  padding:40px 20px;
}
.reader-container{
  max-width:800px;
  margin:0 auto;
  background:white;
  box-shadow:0 10px 30px rgba(0,0,0,0.1);
  padding:60px 80px;
}
</style>
</head>
<body>
<div class="reader-container">

<div class="cover">
<h1>${keyword}</h1>
<p>共收录 ${items.length} 篇文章 · ${new Date().toLocaleDateString()}</p>
</div>
`;

items.forEach((item,index)=>{

  const article = item.json;

  readerHtml += `
  <article style="page-break-before:${index===0?'auto':'always'}">
    <h1>${article.title || '无标题'}</h1>

    <div>
      ${article.siteName || ''}
      ${article.byline ? `作者：${article.byline}`:''}
      ${article.publishedTime ? ` · ${article.publishedTime}`:''}
    </div>

    <div>
      ${article.textcontent || article.content || ''}
    </div>
  </article>
  `;
});

readerHtml += `
</div>
</body>
</html>
`;

// ⭐ 转 base64
const base64Data = Buffer.from(readerHtml).toString('base64');

return [{
  json: {
    // 添加JSON格式的HTML字段，供Make PDF节点使用
    html: readerHtml,  // 这是原始的HTML字符串
  },
  binary:{
    html:{
      data: base64Data,
      mimeType:'text/html',
      fileName:`index.html`
    }
  }
}];

const items = $input.all();
const results = [];

items.forEach((item,index)=>{
    try {
        let rawData = item.json.data;

        if (!rawData) {
            throw new Error('数据为空');
        }

        if (typeof rawData !== 'string') {
            rawData = String(rawData);
        }

        // 清洗转义字符
        rawData = rawData.replace(/\\"/g, '"')
                         .replace(/\\n/g, '\n')
                         .replace(/\\t/g, '\t')
                         .replace(/\\\\/g, '\\');

        // ========== 增强版HTML验证 ==========

        // 1. 基础标签验证
        const hasHtmlTags = /<[^>]+>/g.test(rawData);

        // 2. 检查DOCTYPE (HTML5标准)
        const hasDoctype = /<!doctype\s+html>/i.test(rawData);

        // 3. 检查html根标签
        const hasHtmlTag = /<html[^>]*>/i.test(rawData);
        const hasClosingHtml = /<\/html>/i.test(rawData);

        // 4. 检查head标签
        const hasHeadTag = /<head[^>]*>/i.test(rawData);
        const hasClosingHead = /<\/head>/i.test(rawData);

        // 5. 检查body标签
        const hasBodyTag = /<body[^>]*>/i.test(rawData);
        const hasClosingBody = /<\/body>/i.test(rawData);

        // 6. 检查标题标签
        const hasTitleTag = /<title[^>]*>.*?<\/title>/i.test(rawData);

        // 7. 检查元数据标签
        const hasMetaTags = /<meta[^>]*>/i.test(rawData);

        // 8. 检查基本结构完整性
        const hasBasicStructure = hasDoctype || (hasHtmlTag && hasClosingHtml);

        // 9. 检查内容长度（太短可能是无效HTML）
        const contentLength = rawData.length;
        const isReasonableLength = contentLength > 500;  // 有效HTML通常超过500字符

        // 10. 检查标签平衡（简单版：统计常见标签数量）
        const openTags = (rawData.match(/<[^/][^>]*>/g) || []).length;
        const closeTags = (rawData.match(/<\/[^>]+>/g) || []).length;
        const tagBalance = Math.abs(openTags - closeTags) < 10;  // 标签数量大致平衡

        // 11. 检查是否有文本内容（不仅仅是标签）
        const textContent = rawData.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        const hasTextContent = textContent.length > 100;

        // 12. 检查常见编码声明
        const hasCharset = /charset\s*=\s*["']?utf-8?["']?/i.test(rawData);

        // 13. 检查中文内容个数
        const chineseChars = textContent.match(/[\u4e00-\u9fa5]/g) || [];
        const chineseCount = chineseChars.length;
        // 14. 检查是否可能是JSON而非HTML（快速检测）
        const looksLikeJson = rawData.trim().startsWith('{') || rawData.trim().startsWith('[');

        // ========== 综合评分 ==========

        const validationScore = [
            hasHtmlTags ? 5 : 0,
            hasDoctype ? 10 : 0,
            hasHtmlTag ? 5 : 0,
            hasClosingHtml ? 5 : 0,
            hasHeadTag&&hasClosingHead ? 5 : 0,
            hasBodyTag&&hasClosingBody ? 10 : 0,
            hasTitleTag ? 10 : 0,
            hasMetaTags ? 5 : 0,
            hasBasicStructure ? 20 : 0,
            isReasonableLength ? 10 : 0,
            tagBalance ? 10 : 0,
            hasTextContent ? 10 : 0,
            chineseCount>100 ? 5 : -50,
            !looksLikeJson ? 5 : -20  // 看起来像JSON的直接扣分
        ].reduce((a, b) => a + b, 0);

        // ========== 验证结果 ==========

        const isValid = validationScore >= 50;  // 总分50分以上算有效HTML

        // 详细的验证结果
        const validationDetails = {
            hasHtmlTags,
            hasDoctype,
            hasHtmlTag,
            hasClosingHtml,
            hasHeadTag,
            hasBodyTag,
            hasTitleTag,
            hasMetaTags,
            hasBasicStructure,
            isReasonableLength,
            tagBalance,
            hasTextContent,
            hasCharset,
            chineseCount,
            looksLikeJson,
            openTagsCount: openTags,
            closeTagsCount: closeTags,
            textLength: textContent.length,
            validationScore
        };

        // 提取标题用于验证
        const titleMatch = rawData.match(/<title[^>]*>([^<]+)<\/title>/i);
        const title = titleMatch ? titleMatch[1].trim() : '未找到标题';

        // 提取正文预览
        const bodyMatch = rawData.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
        const bodyPreview = bodyMatch ? bodyMatch[1].substring(0, 300) : '';

        console.log(`第 ${item.json.index || results.length + 1} 个item:`);
        console.log(`- 标题: ${title}`);
        console.log(`- 验证分数: ${validationScore}/100`);
        console.log(`- 是否有效: ${isValid ? '是' : '否'}`);
        console.log(`- 标签数量: 开=${openTags} 关=${closeTags}`);
        console.log(`- 文本长度: ${textContent.length}`);

        results.push({
            json: {
                index: item.json.index || results.length + 1,
                url: $('HTML').first().json.site[index] || '',

                // 清洗后的完整HTML
                cleanedHtml: rawData,

                // 提取的元数据
                title: title,

                // 增强验证结果
                isValid: isValid,
                validationScore: validationScore,
                validationDetails: validationDetails,

                // 预览
                bodyPreview: bodyPreview.substring(0, 500),
                textPreview: textContent.substring(0, 500),

                // 为后续节点准备的binary格式
                binary: {
                    data: {
                        data: Buffer.from(rawData).toString('base64'),
                        mimeType: 'text/html',
                        fileName: `page_${item.json.index || results.length + 1}.html`
                    }
                }
            }
        });

    } catch (error) {
        console.error('处理出错:', error.message);
        results.push({
            json: {
                index: item.json.index || results.length + 1,
                url: item.json.url || '',
                error: error.message,
                isValid: false,
                validationScore: 0,
                validationDetails: { error: error.message },
                cleanedHtml: '<html><body>Error processing content</body></html>',
                title: '处理失败'
            }
        });
    }
})

// 统计
const validItems = results.filter(r => r.json.isValid);
console.log(`\n统计: 总共 ${results.length} 个items`);
console.log(`有效HTML: ${validItems.length} 个`);
console.log(`无效HTML: ${results.length - validItems.length} 个`);

return results;
